import org.springframework.test.web.servlet.MockMvc;

import com.fasterxml.jackson.databind.ObjectMapper;

import br.tcc.checkout.model.ItemCarrinho;
import br.tcc.checkout.model.RequisicaoResumo;
import java.util.ArrayList;
import java.util.List;

@SpringBootTest
@AutoConfigureMockMvc
class CheckoutControllerTest {

	@Autowired
	private MockMvc mockMvc;

	@Autowired
	private ObjectMapper objectMapper;

	@Test
	void testarEndpoint_Sucesso() throws Exception {
		List<ItemCarrinho> itens = new ArrayList<>();
		itens.add(new ItemCarrinho("Camiseta", 79.90, 2, 0.30));
		itens.add(new ItemCarrinho("Tênis", 249.90, 1, 1.20));

		RequisicaoResumo requisicao = new RequisicaoResumo(itens, "EXPRESSA", "BEMVINDO10",
				"PIX", 1);

		mockMvc.perform(post("/checkout/resumo")
				.contentType(MediaType.APPLICATION_JSON)
				.content(objectMapper.writeValueAsString(requisicao)))
				.andExpect(status().isOk())
				.andExpect(jsonPath("$.subtotalProdutos").value(409.70))
				.andExpect(jsonPath("$.descontoCupom").value(40.97))
				.andExpect(jsonPath("$.frete").value(33.10))
				.andExpect(jsonPath("$.prazoEntregaDias").value(2))
				.andExpect(jsonPath("$.ajustePagamento").value(-20.09))
				.andExpect(jsonPath("$.totalFinal").value(381.74))
				.andExpect(jsonPath("$.parcelas").value(1))
				.andExpect(jsonPath("$.valorParcela").value(381.74));
	}

	@Test
	void testarEndpoint_Erro_PedidoInvalido() throws Exception {
		RequisicaoResumo requisicao = new RequisicaoResumo(new ArrayList<>(), "ECONOMICA",
				null, "PIX", 1);

		mockMvc.perform(post("/checkout/resumo")
				.contentType(MediaType.APPLICATION_JSON)
				.content(objectMapper.writeValueAsString(requisicao)))
				.andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
	}

	@Test
	void testarEndpoint_Erro_ModalidadeInvalida() throws Exception {
		List<ItemCarrinho> itens = new ArrayList<>();
		itens.add(new ItemCarrinho("Produto", 10.0, 1, 1.0));

		RequisicaoResumo requisicao = new RequisicaoResumo(itens, "INVALIDA", null, "PIX", 1);

		mockMvc.perform(post("/checkout/resumo")
				.contentType(MediaType.APPLICATION_JSON)
				.content(objectMapper.writeValueAsString(requisicao)))
				.andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.erro").value("MODALIDADE_INVALIDA"));
	}

	@Test
	void testarEndpoint_Erro_CupomInvalido() throws Exception {
		List<ItemCarrinho> itens = new ArrayList<>();
		itens.add(new ItemCarrinho("Produto", 10.0, 1, 1.0));

		RequisicaoResumo requisicao = new RequisicaoResumo(itens, "ECONOMICA", "INVALIDO",
				"PIX", 1);

		mockMvc.perform(post("/checkout/resumo")
				.contentType(MediaType.APPLICATION_JSON)
				.content(objectMapper.writeValueAsString(requisicao)))
				.andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.erro").value("CUPOM_INVALIDO"));
	}
}

