java -jar target/checkout-0.0.1-SNAPSHOT.jar > /tmp/app.log 2>&1 &
APP_PID=$!
sleep 8

echo "Teste 1: Exemplo 2 (ECONOMICA, 6 parcelas, sem cupom)"
curl -s -X POST http://localhost:8080/checkout/resumo \
  -H "Content-Type: application/json" \
  -d '{
    "itens": [
      {"nome": "Camiseta", "precoUnitario": 79.90, "quantidade": 2, "pesoKg": 0.30},
      {"nome": "Tênis", "precoUnitario": 249.90, "quantidade": 1, "pesoKg": 1.20}
    ],
    "modalidadeEntrega": "ECONOMICA",
    "formaPagamento": "CARTAO",
    "parcelas": 6
  }' | grep -o '"totalFinal":[^,}]*\|"valorParcela":[^,}]*'

echo -e "\n\nTeste 2: Motoboy (deve falhar se peso > 5kg)"
curl -s -X POST http://localhost:8080/checkout/resumo \
  -H "Content-Type: application/json" \
  -d '{
    "itens": [
      {"nome": "Produto", "precoUnitario": 10.0, "quantidade": 1, "pesoKg": 6.0}
    ],
    "modalidadeEntrega": "MOTOBOY",
    "formaPagamento": "PIX"
  }' | grep -o '"erro":"[^"]*"'

echo -e "\n\nTeste 3: Cupom MENOS50 sem atingir R$ 300"
curl -s -X POST http://localhost:8080/checkout/resumo \
  -H "Content-Type: application/json" \
  -d '{
    "itens": [
      {"nome": "Produto", "precoUnitario": 10.0, "quantidade": 1, "pesoKg": 1.0}
    ],
    "modalidadeEntrega": "ECONOMICA",
    "cupom": "MENOS50",
    "formaPagamento": "PIX"
  }' | grep -o '"erro":"[^"]*"'

echo -e "\n\nTeste 4: Boleto acima de R$ 1000"
curl -s -X POST http://localhost:8080/checkout/resumo \
  -H "Content-Type: application/json" \
  -d '{
    "itens": [
      {"nome": "Produto", "precoUnitario": 1001.0, "quantidade": 1, "pesoKg": 1.0}
    ],
    "modalidadeEntrega": "RETIRADA_LOJA",
    "formaPagamento": "BOLETO"
  }' | grep -o '"erro":"[^"]*"'

kill $APP_PID 2>/dev/null
sleep 1

